#include <string>
#include <wjr/container/btree_map.hpp>
#include <wjr/container/btree_set.hpp>
#include <wjr/container/experimental/compact_btree_map.hpp>

#define SEARCH(N) \
extern "C" unsigned search##N(const int *values, unsigned size, int key) { \
    return wjr::basic_btree_searcher_impl<N>::search<1>(size, [=](unsigned i) { return values[i] >= key; }); \
}
SEARCH(4)
SEARCH(5)
SEARCH(8)
SEARCH(9)
SEARCH(16)
SEARCH(17)
SEARCH(32)
SEARCH(64)

using map16 = wjr::btree_map<int, int>;
using strings = wjr::btree_map<std::string, int, std::less<>>;
using set32 = wjr::btree_set<unsigned long long, std::less<>, std::allocator<char>, 32>;
using compact64 = wjr::experimental::compact_btree_map<int, int, std::less<>, std::allocator<char>, 64>;
extern "C" auto map_bound(const map16 &tree, int key) { return tree.lower_bound(key); }
extern "C" auto map_upper(const map16 &tree, int key) { return tree.upper_bound(key); }
extern "C" auto string_bound(const strings &tree, std::string_view key) { return tree.lower_bound(key); }
extern "C" auto set_bound(const set32 &tree, unsigned long long key) { return tree.lower_bound(key); }
extern "C" auto compact_bound(const compact64 &tree, int key) { return tree.lower_bound(key); }
extern "C" const size_t layouts[] = { sizeof(map16), alignof(map16), sizeof(map16::iterator),
    sizeof(strings), sizeof(set32), sizeof(compact64), alignof(compact64),
    sizeof(wjr::basic_btree_searcher_impl<16>), sizeof(wjr::basic_btree_searcher_impl<64>) };
